// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testRegression_property() public {
        uint64 _number = 1;
        uint64 _timestamp = 100;
        uint256 _basefee = 200;
        bytes32 _hash = keccak256("test");
        uint64 _sequenceNumber = 3;
        bytes32 _batcherHash = bytes32(uint256(4));
        uint256 _l1FeeOverhead = 5;
        uint256 _l1FeeScalar = 6;

        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        vm.prank(depositor);
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);

        assertTrue(c.hash() == _hash, "hash should be set to the provided value");
    }
}
